def invalidate(self, changed: str) -> None:
    pending = [changed]
    seen: set[str] = set()
    while pending:
        name = pending.pop()
        if name in seen:
            continue
        seen.add(name)
        self._cache.pop(name, None)
        pending.extend(self.graph.dependents(name))

